/** ⑤ 报事报修：历史累计取累计口径，其余页签取当月口径；工单构成按 repairNum/incidentNum 实时计算。 */
const repairTabs = ['历史累计', '当月数据', '图表走势']
const repairTab = ref('当月数据')
const repair = computed(() => {
  const history = repairTab.value === '历史累计'
  const r = history ? stats.repair : (statsCur.repair ?? stats.repair)
  const prefix = history ? '历史' : '本月'
  const repairNum = num(r?.repairNum)
  const incidentNum = num(r?.incidentNum)
  const total = (repairNum ?? 0) + (incidentNum ?? 0)
  const rawRate = r?.satisfactionRate
  const rate = typeof rawRate === 'string' && rawRate.includes('%') ? rawRate : (num(rawRate) !== undefined ? `${num(rawRate)}%` : DASH)
  return {
    labels: [
      `${prefix}新增工单数（件）`,
      `${prefix}已完成工单数（件）`,
      `${prefix}未完成工单数（件）`,
      '满意度占比',
    ],
    stats: [
      [fmt(r?.monthAddNum), 'desc', 'primary'],
      [fmt(r?.monthCompletedNum), 'done', 'emerald'],
      [fmt(r?.monthUncompletedNum), 'pending', 'secondary'],
      [rate, 'star', 'error'],
    ],
    parts: [
      { n: fmt(repairNum), pc: pct(repairNum, total) },
      { n: fmt(incidentNum), pc: pct(incidentNum, total) },
    ],
  }
})

/** 图表走势：消费累计口径 stats.repair.trendList，三序列（新增柱/已完成/未完成折线），空值按 0，空数组走空态。 */
const repairTrend = computed(() => {
  const rows = (stats.repair?.trendList ?? []).map(t => ({
    month: t?.month ?? '',
    add: num(t?.addNum) ?? 0,
    done: num(t?.completedNum) ?? 0,
    undone: num(t?.uncompletedNum) ?? 0,
  }))
  if (!rows.length) return null
  const maxVal = Math.max(1, ...rows.flatMap(r => [r.add, r.done, r.undone]))
  const W = 320, H = 150, left = 34, right = 10, top = 12, bottom = 34
  const plotW = W - left - right, plotH = H - top - bottom
  const step = plotW / rows.length
  const y = (v: number) => top + plotH - (v / maxVal) * plotH
  const cx = (i: number) => left + step * (i + 0.5)
  const barW = Math.min(18, step * 0.4)
  return {
    bars: rows.map((r, i) => ({ x: cx(i) - barW / 2, y: y(r.add), w: barW, h: top + plotH - y(r.add) })),
    donePts: rows.map((r, i) => `${cx(i)},${y(r.done)}`).join(' '),
    undonePts: rows.map((r, i) => `${cx(i)},${y(r.undone)}`).join(' '),
    grids: [0, 0.5, 1].map(f => ({ y: top + plotH - f * plotH, label: fmt(Math.round(maxVal * f)) })),
    months: rows.map((r, i) => ({ x: cx(i), label: r.month })),
  }
})

